"use strict";
// Additive reader view. Recall never writes the study-record/attempt protocol.
(() => {
 const P=window.STUDY_COURSE,T=window.STUDY_COMPLETE_TOPICS,D=window.STUDY_TOPIC_RECALL_CARDS;
 if(!P||!T||!D||typeof document==='undefined')return;
 const KEY='zhixu-topic-recall-v1',VERSION='20261107.1',MAX=262144;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const rich=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 // Whole-answer matching only. Preserve negation, minus signs, operators and word order.
 const normalize=s=>String(s??'').normalize('NFKC').trim().replace(/\s+/g,'').replace(/[。.!！?？]+$/g,'').toLowerCase();
 function judge(value,blank){const v=normalize(value);if(!v)return{status:'empty',label:'未填'};if([blank.answer,...(blank.accept||[])].some(x=>normalize(x)===v))return{status:'correct',label:'正确'};const trap=(blank.traps||[]).find(x=>x.answers.some(a=>normalize(a)===v));return trap?{status:'wrong',label:'需订正',hint:trap.hint}:{status:'review',label:'表述待核对',hint:'尚未识别这句话，请对照标准答案自查。'};}
 const fresh=()=>({mode:'cards',values:{},submitted:false,revealed:false,confirmReset:false});
 let sessions={},storageWarning=false,restoredTopics={};
 const hydratedTopics=new Set();
 try{const raw=sessionStorage.getItem(KEY);if(raw&&raw.length<=MAX){const data=JSON.parse(raw);if(data?.version===VERSION&&data.topics&&typeof data.topics==='object'){restoredTopics=data.topics;for(const [id,cards]of Object.entries(D)){const s=data.topics[id];if(!s||typeof s!=='object')continue;const next=fresh();next.mode=s.mode==='quiz'?'quiz':'cards';next.submitted=s.submitted===true;next.revealed=s.revealed===true;for(const c of cards)c.blanks.forEach((_,i)=>{const key=c.id+':'+i;if(typeof s.values?.[key]==='string')next.values[key]=s.values[key].slice(0,100);});sessions[id]=next;}}}}catch(_){storageWarning=true;}
 const state=id=>{
  const next=sessions[id]||(sessions[id]=fresh());
  // Content extensions may register additional blanks after this script loads.
  // Hydrate them once, when the complete topic is first used; never resurrect reset answers.
  if(!hydratedTopics.has(id)){
   hydratedTopics.add(id);const old=restoredTopics[id];
   for(const card of D[id]||[])card.blanks.forEach((_,i)=>{const key=card.id+':'+i;if(typeof old?.values?.[key]==='string'&&next.values[key]===undefined)next.values[key]=old.values[key].slice(0,100);});
  }
  return next;
 };
 function save(){try{sessionStorage.setItem(KEY,JSON.stringify({version:VERSION,topics:sessions}));storageWarning=false;}catch(_){storageWarning=true;}}
 function foot(){return `<p class="recall-foot" data-recall-storage>${storageWarning?'本轮暂时无法保存，刷新可能丢失答案。':'本轮答案仅在当前标签页临时保存，不纳入学习备份或刷题成绩。'}</p>`;}
 function result(c,s){return `<ul class="recall-answer-list">${c.blanks.map((b,i)=>{const j=judge(s.values[c.id+':'+i],b);return `<li class="recall-${j.status}"><strong>第 ${i+1} 空 · ${s.submitted?j.label:'参考答案'}</strong><span>标准答案：<b>${esc(b.answer)}</b></span>${s.submitted&&j.hint?`<small>${esc(j.hint)}</small>`:''}</li>`;}).join('')}</ul>`;}
 function summary(cards,s){if(!s.submitted)return s.revealed?'已展开参考答案。本轮不作检验结果，重新自测时再试。':'';const all=cards.flatMap(c=>c.blanks.map((b,i)=>judge(s.values[c.id+':'+i],b)));return `${all.filter(j=>j.status==='correct').length} / ${all.length} 空正确 · ${all.filter(j=>j.status==='empty').length} 空未填 · ${all.filter(j=>j.status==='wrong').length} 空需订正 · ${all.filter(j=>j.status==='review').length} 空待核对`+(s.revealed?'（本轮已看过参考答案）':'');}
 function render(id){const cards=D[id];if(!cards)return'';const s=state(id),topic=T.topics.find(t=>t.id===id);return `<section class="topic-block topic-recall" id="topic-recall" data-topic-recall-id="${id}" tabindex="-1"><header class="recall-header"><div><span class="topic-eyebrow">学后回忆</span><h2>记忆卡与填空自测</h2><p>1 张专题汇总卡 · ${cards.length} 组填空，学完整体再检验回忆。</p></div><span class="recall-badge">专题汇总</span></header><div class="recall-mode" role="group" aria-label="选择记忆或自测"><button type="button" data-recall-action="cards" aria-pressed="${s.mode==='cards'}">看记忆卡</button><button type="button" data-recall-action="quiz" aria-pressed="${s.mode==='quiz'}">合上卡片 · 填空</button></div>${s.mode==='cards'?`<article class="recall-card recall-topic-card"><header class="recall-topic-title"><span>专题记忆卡</span><h3>${esc(topic.title)}</h3></header><ul class="recall-topic-points">${cards.map(c=>`<li><h4>${esc(c.title)}</h4><p class="recall-core">${rich(c.core)}</p><p class="recall-boundary">${rich(c.boundary)}</p></li>`).join('')}</ul><button type="button" class="recall-source" data-topic-scroll="topic-top">回看完整讲解 ↑</button></article><div class="recall-actions"><button class="btn" type="button" data-recall-action="quiz">记好了，开始填空</button></div>`:`<form data-recall-form="${id}" autocomplete="off"><p class="recall-instruction">每空填关键词；提交后逐空核对。未识别的表达留给你对照，不直接判错。</p><div class="recall-question-list">${cards.map((c,n)=>`<fieldset class="recall-question"><legend>${String(n+1).padStart(2,'0')} · ${esc(c.quizTitle||c.title)}</legend><p class="recall-sentence">${c.prompt.split(/\{\{(\d+)\}\}/g).map((part,i)=>i%2?`<input type="text" inputmode="text" maxlength="100" spellcheck="false" aria-label="第 ${n+1} 题第 ${Number(part)+1} 空" data-recall-blank="${c.id}:${part}" value="${esc(s.values[c.id+':'+part]||'')}" placeholder="第 ${Number(part)+1} 空">`:esc(part)).join('')}</p><div class="recall-card-result" ${s.submitted||s.revealed?'':'hidden'}>${s.submitted||s.revealed?result(c,s):''}</div></fieldset>`).join('')}</div><p class="recall-score" data-recall-score role="status" aria-live="polite" tabindex="-1" ${s.submitted||s.revealed?'':'hidden'}>${summary(cards,s)}</p><div class="recall-actions"><button class="btn" type="submit">${s.submitted?'重新核对':'提交核对'}</button><button class="btn secondary" type="button" data-recall-action="reveal">显示参考答案</button><button class="btn secondary" type="button" data-recall-action="reset">重新自测</button></div>${s.confirmReset?'<div class="recall-reset-confirm" role="group" aria-label="确认重新自测"><p>清空本专题这一轮填空，开始新一轮？</p><button type="button" class="btn" data-recall-action="reset-confirm">清空并重新填</button><button type="button" class="btn secondary" data-recall-action="reset-cancel">保留答案</button></div>':''}</form>`}<p class="recall-scope">一张卡汇总本专题主干；完整条件与例解见上文。</p>${foot()}</section>`;}
 const oldRender=P.render;
 P.render=(...args)=>{const html=oldRender(...args),parts=args[0],id=parts[3];if(parts[2]!=='topic'||!D[id])return html;const tmp=document.createElement('template');tmp.innerHTML=html;const root=tmp.content.querySelector('[data-complete-topic]');if(!root)return html;root.querySelector('#topic-practice').insertAdjacentHTML('beforebegin',render(id));root.querySelector('[data-topic-scroll="topic-practice"]').insertAdjacentHTML('beforebegin','<button type="button" data-topic-scroll="topic-recall">记忆卡与填空自测</button>');root.querySelector('option[value="topic-practice"]').insertAdjacentHTML('beforebegin','<option value="topic-recall">记忆卡与填空自测</option>');return tmp.innerHTML;};
 function replace(root,focus){const id=root.dataset.topicRecallId;root.outerHTML=render(id);const next=document.querySelector('[data-topic-recall-id="'+id+'"]');const target=next.querySelector(focus)||next;target.focus({preventScroll:true});if(focus?.includes('score'))target.scrollIntoView({behavior:'auto',block:'center'});}
 document.addEventListener('input',e=>{const input=e.target;if(!input.matches?.('[data-recall-blank]'))return;const root=input.closest('[data-topic-recall-id]'),s=state(root.dataset.topicRecallId);s.values[input.dataset.recallBlank]=input.value.slice(0,100);s.confirmReset=false;if(s.submitted){s.revealed=true;s.submitted=false;root.querySelectorAll('.recall-card-result').forEach(el=>{el.hidden=true;el.innerHTML='';});const score=root.querySelector('[data-recall-score]');score.hidden=false;score.textContent='答案已修改，请重新核对。';}save();root.querySelector('[data-recall-storage]').outerHTML=foot();});
 document.addEventListener('submit',e=>{const form=e.target;if(!form.matches?.('[data-recall-form]'))return;e.preventDefault();const root=form.closest('[data-topic-recall-id]'),s=state(root.dataset.topicRecallId);form.querySelectorAll('[data-recall-blank]').forEach(input=>{s.values[input.dataset.recallBlank]=input.value.slice(0,100);});s.submitted=true;s.confirmReset=false;save();replace(root,'[data-recall-score]');});
 document.addEventListener('click',e=>{const b=e.target.closest?.('[data-recall-action]');if(!b)return;const root=b.closest('[data-topic-recall-id]'),id=root.dataset.topicRecallId,s=state(id),action=b.dataset.recallAction;let focus='[data-recall-action="'+action+'"]';if(action==='cards'||action==='quiz'){s.mode=action;s.confirmReset=false;if(action==='quiz')focus='[data-recall-blank]';}else if(action==='reveal'){s.revealed=true;s.confirmReset=false;focus='[data-recall-score]';}else if(action==='reset'){s.confirmReset=true;focus='[data-recall-action="reset-confirm"]';}else if(action==='reset-cancel'){s.confirmReset=false;focus='[data-recall-action="reset"]';}else if(action==='reset-confirm'){sessions[id]=fresh();sessions[id].mode='quiz';focus='[data-recall-blank]';}save();replace(root,focus);});
 window.STUDY_TOPIC_RECALL={cards:D,judge,normalize,render,storageKey:KEY,version:VERSION};
})();
